#!ibl edition=2
[def:대상별좁혀읽기]($대상,$루트,$파일패턴="*.py",$앞줄=2,$뒷줄=29,$검색상한=20) {
  $설정 = [self:script]{id:"코드조사범위",args:{op:"prepare",targets:$대상,before:$앞줄,after:$뒷줄,limit:$검색상한}}
  $검색 = $설정.targets >> [table:each]{parallel:4} {
    [if:$it.problem != ""] { return {name:$it.name,problem:$it.problem} }
    [try] {
      $결과 = [self:grep]{pattern:$it.pattern,path:$루트,file_pattern:$파일패턴,regex:true,output_mode:"content",limit:$설정.limit + 1}
      return {name:$it.name,result:$결과}
    } [catch] { return {name:$it.name,problem:$error.message} }
  }
  $계획 = [self:script]{id:"코드조사범위",args:{op:"plan",config:$설정,searches:$검색}}
  $본문 = $계획.ranges >> [table:each]{parallel:4} {
    [try] {
      $값 = [self:read]{path:$it.path,start_line:$it.start_line,end_line:$it.end_line,numbered:false}
      return {id:$it.id,result:$값}
    } [catch] { return {id:$it.id,problem:$error.message} }
  }
  return [self:script]{id:"코드조사범위",args:{op:"finish",plan:$계획,reads:$본문}}
}
